        BetaItem(id: "A-SHOP-06", title: "Share, copy and export a complete list", category: "Shopping List", how: "Copy/share, TXT and CSV include all intended items and quantities, correctly escape CSV delimiters/newlines, and handle an empty list without malformed output.", auto: false, revision: "053d0a437c57a94a05bed6f34f347b9966c15aaee7bf4f8a475ff98e6c34fdc4"),
        BetaItem(id: "A-SET-01", title: "Persist user preferences", category: "Settings and data management", how: "Preferences persist after relaunch; settings intended to be local remain local; units are reflected consistently in recipe details and Cook Mode.", auto: false, revision: "bcafeb6da9f8724635f9d7541e99c94026823f403720c932ed2f1b9f70a605dd"),
        BetaItem(id: "A-SET-02", title: "Export user data", category: "Settings and data management", how: "Export completes with a clear success/failure state and creates a versioned JSON archive containing local recipes, shopping items, nutrition diary entries with source/nutrient snapshots, nutrition goals, app/timer preferences and export metadata, without credentials or session tokens. Import merges recipes, shopping items and diary entries by stable ID (existing on-device items win), while goals and preferences replace current values only after confirmation. Legacy recipe-array exports remain importable.", auto: false, revision: "307ff4d07cae3016de5922d096355c0db6246cae6b50d683fac80bea502a2819"),
        BetaItem(id: "A-SET-03", title: "Import and validate data", category: "Settings and data management", how: "Valid current archives and legacy recipe arrays import safely; malformed/unsupported versions and invalid diary entries are rejected with a useful error; recipes, shopping items and diary entries with matching IDs keep the on-device copy; imported goals and preferences replace current values only after confirmation; import does not silently destroy valid local data.", auto: false, revision: "e16bceeecc967b1cef2da9a843e1774a1ee514baa1f292d258bb9c87a68f5965"),
        BetaItem(id: "A-SET-04", title: "Clear local data safely", category: "Settings and data management", how: "Confirmation describes exactly what is removed and retained; operation reports failure truthfully; app returns to a usable empty/onboarding state without stale data, including food diary entries and nutrition goals.", auto: false, revision: "7202b8520fcc222d1ec5cad67493babcdb5072500b40ab50b08af9616b9bf705"),
        BetaItem(id: "A-SET-05", title: "Beta-channel diagnostics fail closed", category: "Settings and data management", how: "Recognized beta channels expose Beta testing; Production, empty and unknown channels hide the entry/banner even with QA launch arguments in an installed archive. Verify TierA and Production/empty builds.", auto: false, revision: "486483aee11c5e2b545cabbce41f5ce8dd5f44a066d9da362e23521c88331698"),
        BetaItem(id: "A-SET-06", title: "Accurate build identity and legal/help destinations", category: "Settings and data management", how: "Version, build, short SHA, backend identity and release channel are accurate; copy action works; privacy, terms and support links open the intended destinations and failures are understandable.", auto: false, revision: "5f6b4bb37a67494e908ff0d69fc7b1a95cb3ddb1f972bb10fd5b54d5fdf5d6ef"),
        BetaItem(id: "A-DATA-01", title: "Corrupt store recovers", category: "Data safety & security", how: "A broken on-device store is moved to Backups/ate-<timestamp>.store, a fresh store opens, recipes come back from sync when signed in, a 'Library repaired' screen offers a JSON export, and the app never crashes.", auto: true, revision: "536b48bb1bebdbce70c2be457f2b446e8012f2607a32f6e1859ac7e680a8ec5b"),
        BetaItem(id: "A-DATA-02", title: "Save failures are visible", category: "Data safety & security", how: "Every SwiftData save goes through StoreSaver: 2 retries, an os_log error, and a non-blocking error banner; on-screen state is kept.", auto: true, revision: "d9be2ad2ecc5617f0c9d087717dc93fd2989233bce9b29d3b1846466b8c4a150"),
        BetaItem(id: "A-AUTH-01", title: "Sign up + email confirmation", category: "Auth", how: "Given a new email, When I sign up, Then I see \"check your email\", and tapping the link opens Ate signed in.", auto: true, revision: "f6c3329309f29731f25378018dc8ac0ba11198f5b3f3698f5df693c85982b3ae"),
