        BetaItem(id: "A-AUTH-03", title: "Sign in / sign out (keep vs remove local data)", category: "Auth", how: "Given signed in, When I choose \"keep recipes\", Then local data stays; When I choose \"remove local data\", Then recipes, shopping list, food diary, nutrition goals and local settings are wiped.", auto: true, revision: "85566c9f8328d46f60193949befc58ed361f98d01e852379180166a3f6aa6d4c"),
        BetaItem(id: "A-AUTH-04", title: "Magic link (incl. after reinstall)", category: "Auth", how: "Given I requested a magic link, When I delete and reinstall Ate and then tap the link, Then Ate opens and signs me in (or says the link expired and offers a new one).", auto: true, revision: "3069337ac8f295ff732380d07d877ef4c23ec93234b77879ca131ff860e37015"),
        BetaItem(id: "A-AUTH-05", title: "Password reset, incl. link opened on another device", category: "Auth", how: "Given a reset email, When I open it on the same iPhone, Then Ate shows set-new-password; When opened on another device, Then a clear page says to open it on the iPhone (no dead end).", auto: true, revision: "ded7387ae009ef2795451b3f845353b4dabf1bdbf1289af85ae0ad9798da8bca"),
        BetaItem(id: "A-AUTH-06", title: "Expired session refresh", category: "Auth", how: "Given an expired access token with a valid refresh token, Then the next sync refreshes silently; Given both expired, Then a friendly \"please sign in again\" shows and local data is untouched.", auto: true, revision: "3def9820f7b4ef0c8cdb764158349a3747c10cded7609abee8487c2407cd9918"),
        BetaItem(id: "A-AUTH-07", title: "Two-device sign-in", category: "Auth", how: "Given account X on phones A and B, Then both stay signed in and sync; signing out on A does not sign out B.", auto: false, revision: "7d3d0224c213cc55fd5ecbe1dc0ffd4ed4bc3862f9c84a335afa75c86c3f7909"),
        BetaItem(id: "A-AUTH-08", title: "Delete account", category: "Auth", how: "Given signed in, When I delete my account and confirm, Then the auth user and synced rows are gone server-side, local recipes/shopping/diary/goals are cleared, and I'm signed out.", auto: true, revision: "6c6ecd33180d7471c738fbb6e30d7dd83d74aa33f1948245e65935bfe6a9258c"),
        BetaItem(id: "A-AUTH-09", title: "REAL-DEVICE AUTH GATE", category: "Auth", how: "All of A-AUTH-01…08 pass on iPhone 17 against production Supabase and are recorded in QA_MATRIX.", auto: false, revision: "df605afe5c4af8d4f0fcd50d8e6c92f54ebebaab3f0de11061a024ac8c41fb12"),
        BetaItem(id: "A-SYNC-01", title: "Sync recipes across devices", category: "Sync", how: "Given signed in on A and B, When I edit on A and sync, Then B shows the edit after pull-to-refresh within 10 s.", auto: true, revision: "b2f29f4e0120a2940a2c07f478c9f600ada7ac903ec9c88dd532b0069e320741"),
        BetaItem(id: "A-SYNC-02", title: "Sync conflicts (last write wins)", category: "Sync", how: "Given both phones edit offline, When both sync, Then the newer edit wins entirely and nothing is duplicated.", auto: false, revision: "a4b76ce3367507ed9f77f4e51a01c34f6d9895009401615ba09b29a6587b23fe"),
        BetaItem(id: "A-SYNC-03", title: "Deletions / tombstones, duplicate IDs, stale references", category: "Sync", how: "Given a delete on A, Then it disappears on B and never resurrects; repeated syncs never create duplicate IDs; a shopping item pointing at a deleted recipe shows without crashing.", auto: false, revision: "d5967d027e60666c415442af5e58c68b6c13f304c609408d7af66b81cb5a19ed"),
        BetaItem(id: "A-SYNC-04", title: "Sync after backgrounding / failure", category: "Sync", how: "Given sync failed or the app was backgrounded for >1 h, When I return to the foreground, Then sync retries once, the local library is unchanged on failure, and a non-blocking error shows.", auto: true, revision: "f30bb1cf116df0680489be875bc2c2991a8ac37354170469ba3675f432e13f21"),
        BetaItem(id: "A-SYNC-05", title: "Account switching is safe", category: "Sync", how: "Given account X's recipes kept locally, When I sign in as Y, Then X's recipes are not uploaded into Y and I'm asked what to do.", auto: true, revision: "86fa92cf1e5d2763474e59db6f88097af30af2fa53f034f64389bbdf79fe5b1e"),
        BetaItem(id: "A-SYNC-06", title: "Migration from older local data", category: "Sync", how: "Given a library saved by build 14, When I install the new build over it, Then every recipe opens with its fields, and new fields default sensibly.", auto: false, revision: "b7833f0184cd175721104e36d856bf3a76d3dc9aa78e0ebbcc380d8da4a339fb"),
        BetaItem(id: "A-SHARE-01", title: "Share a recipe link", category: "Share + deep link", how: "Given a saved recipe, When I tap Share link, Then exactly one link is sent and it resolves on the backend.", auto: true, revision: "523c8874e5f776e614f39c75c246d43bfe4765abfdb0cfa40b185520cf9a432c"),
        BetaItem(id: "A-SHARE-02", title: "Open a shared recipe in the app", category: "Share + deep link", how: "Given `ate://recipe/<slug>`, Then it opens and can be saved; an unknown slug shows \"not found\".", auto: true, revision: "6aee309181519aac46bf9c1644818ec6dff36bf3328dbc2d1e111b1c429043c0"),
        BetaItem(id: "A-SHARE-03", title: "Share link renders on the web", category: "Share + deep link", how: "Given a new share, When opened in any browser, Then the page shows title, ingredients and steps within 3 s.", auto: false, revision: "26081987fba9ce01a3602c1263a9f043e479323915f5bfbb1a10b14d9bf745a5"),
        BetaItem(id: "A-SHARE-04", title: "One real share round trip app → web → app", category: "Share + deep link", how: "Given a share from phone A, Then the web page renders it AND its \"Open in Ate\" button opens the recipe on phone B.", auto: false, revision: "16d75fce7d17071f08929fdb29c7498471fc849d3c8b25bd493c24d7d46e9824"),
        BetaItem(id: "A-SHARE-05", title: "Backend unavailable fallback", category: "Share + deep link", how: "Given Supabase unreachable, Then sharing offers a visible error with Retry or Share as text and everything local still works.", auto: true, revision: "92bcc5535c28ea3a4321d79e89e482562adfebc2e1471c788da504c42e5c63f1"),
        BetaItem(id: "A-OFF-01", title: "Use the app offline", category: "Offline", how: "Given airplane mode, Then browse, search, filter, edit, cook, timers and shopping list all work with no error dialogs.", auto: false, revision: "2c44c53cc378fec1a05498d55cd9571a8c3dffb21270adb6b9e942edea9b4824"),
        BetaItem(id: "A-OFF-02", title: "Retry after network loss", category: "Offline", how: "Given an import/share/sync failed offline, When the network returns and I tap Retry, Then it succeeds without re-entering anything.", auto: true, revision: "41da6cc5eb4b3dd195addca301773b6f136255370ce1209e679720348ab1ec6f"),
        BetaItem(id: "A-SEC-01", title: "RLS on every table", category: "Data safety & security", how: "Every public table has RLS on; user tables are owner-only (auth.uid() = user_id), no anon policies.", auto: true, revision: "d9f900378be28e565bf18f46bb04f3191c2ec1940bd92e72c5bbd422b9f3b44e"),
        BetaItem(id: "A-SEC-02", title: "Anon key is read-only for shares", category: "Data safety & security", how: "With the anon key, user_recipes and qa_results can't be read or written and shared_recipes can't be inserted directly.", auto: true, revision: "991ec4d64b031128d69e2321e1519fb4119466097b1a70f9d091b3c4c9142c61"),
        BetaItem(id: "A-SEC-03", title: "Other users are walled off", category: "Data safety & security", how: "Another user's token can't read, update, delete or spoof rows, and users can't write ci QA rows.", auto: true, revision: "8d78d01deb81fcf8bad6b013b87c1eed0f5381a8cfbd6a7653e229acf2a10c3d"),
        BetaItem(id: "A-SEC-04", title: "Edge Functions check auth and input", category: "Data safety & security", how: "delete-account needs a user JWT; publish-recipe rejects missing/forged auth, bad shapes, overlong and oversized input; get-shared-recipe validates slugs; rate limits respond 429.", auto: true, revision: "996e028597264e84d8878a85ba810963cbdeab0a1ef8ef1ee5b2a6755d202134"),
        BetaItem(id: "A-SEC-05", title: "Auth settings hardened", category: "Data safety & security", how: "Password min 8 with letters+digits, email confirmation on, email OTP ≤ 1 h, leaked-password check reported.", auto: true, revision: "0723f76f230549c873bbee839e39b75ea81498690c4b10e457940a46d76bd3fe"),
        BetaItem(id: "A-SEC-06", title: "Storage, grants and functions reviewed", category: "Data safety & security", how: "Storage buckets, anon grants and function search_path are inventoried; open findings land in docs/SECURITY_REVIEW.md.", auto: true, revision: "4f160ca7412bbe500889a6316458955a9aef8a24fb90ee89f209b04eec2a5741"),
        BetaItem(id: "A-REL-01", title: "Launch cleanly, incl. with corrupted local data", category: "Reliability", how: "Given a corrupted or unreadable local store, Then Ate launches, keeps a backup of the bad file, shows a message, and (if signed in) re-pulls from sync. Cold launch ≤2 s on iPhone 17.", auto: true, revision: "b532ae40cff6017caf533dbcc2eb9d86dcee55532306829ebf9f9cde5aa420c4"),
        BetaItem(id: "A-CI-01", title: "CI builds a numbered IPA on every push", category: "Build/test automation", how: "Given a push to main, Then `Build IPA` publishes `Ate-<ver>-build<N>.ipa` as a release in ≤10 min.", auto: true, revision: "3519056c9875e23cb11c17733592b84d9e1fb62d4c35125a720f756253d996b6"),
        BetaItem(id: "A-CI-02", title: "Unit + key-flow QA tests gate releases", category: "Build/test automation", how: "Given a release candidate, Then AteTests and KeyFlowsQATests pass in CI on the same commit (run with the workflow's run_tests input).", auto: false, revision: "1b90aaf6f759daa7b307495f3e6d48bc7812699e61316eb4937cde1011544421"),
        BetaItem(id: "A-CI-03", title: "Smoke-test the generated IPA", category: "Build/test automation", how: "Given the release IPA, When installed on a simulator (CI) and on iPhone 17 (manual), Then it launches to the Library and can add a prompt recipe.", auto: false, revision: "65eee4e9a43450b6dfd3dfa88451202258112c67e8146ec51cfd02cd03194034"),
        BetaItem(id: "A-CI-04", title: "Release artifact integrity", category: "Build/test automation", how: "Given a release, Then it contains a SHA-256 checksum, the bundle includes AteShare + AteWidgets, and version/build in Info.plist match the release name.", auto: false, revision: "a148fe04f57c619bbecf8c89202acb190fb14474559ff892f6183f9cea2fe869"),
        BetaItem(id: "A-DEV-01", title: "Real-device smoke test of the 8 key flows", category: "Real-device smoke test", how: "Given the pilot build on iPhone 17, Then all 8 QA.md flows pass and the result is recorded in QA_MATRIX.", auto: false, revision: "5ef6caa315f5db5f47028bf96bad0e3510b6692c853c39fb1294a4b7099c975f"),
        BetaItem(id: "A-LAUNCH-01", title: "Pilot users understand it's beta", category: "Pilot readiness", how: "Onboarding/About says \"Beta\"; each tester gets BETA.md + SUPPORT.md (7-day expiry, how to report bugs) before install and confirms they read it.", auto: true, revision: "2f42f19c1f60729ff4343d6bfa60022bd7652859015800ff2b4160ce2dbc40a5"),
        BetaItem(id: "A-CI-05", title: "Docs IDs never drift", category: "Data safety & security", how: "CI fails when an item ID exists in MVP_CHECKLIST, QA_MATRIX or the in-app Beta checks but not the others, or when BetaChecklist.swift is stale, or a service-role key appears in the client.", auto: true, revision: "c9692acce40084b9a0c2301284b9ac64e368d634fd6503be95c3a3eb30e43567"),
        BetaItem(id: "A-CI-06", title: "Published IPA verified", category: "Data safety & security", how: "Each release publishes <ipa>.sha256 and the SHA-256 in the notes; the smoke step downloads the published asset, verifies the checksum, version/build, bundle ID, extensions (widgets, watch), entitlements, privacy manifest, app icon and size limits, and withdraws the release on failure.", auto: true, revision: "65a389d66fbb8562a423ed4276f57b4fdb13e6211184010a93321a7bf36c870d"),
    ]
