        BetaItem(id: "C-DES-05", title: "Segmented servings control", category: "Design review polish", how: "Servings uses a system segmented/stepper control; changing it rescales every ingredient instantly and VoiceOver reads the value.", auto: false, revision: "d6b95cf30b73bf4055ed16655a0a1dbc6b61f88454e2c931061bc27eabdc400b"),
        BetaItem(id: "C-AI-01", title: "80% confidence threshold", category: "Recipe quality", how: "A generated card under 80% confidence isn't shown as a recipe: Ate asks 'What dish is this?' pre-filled with its guesses; after you confirm, it regenerates; if still under 80% it shows 'Draft, needs your input' with Save disabled until you edit or confirm. 80%+ skips the question.", auto: false, revision: "1bed497d0d54a885672aaf9fca67dd29449e7edaf416077f45e133bb1a3cf424"),
        BetaItem(id: "C-AI-02", title: "Main dishes meet the bar", category: "Recipe quality", how: "A generated main dish has at least 4 ingredients with quantities, oven steps give °C, and no vague steps like 'cook ribs'; otherwise it's a draft listing what's missing.", auto: false, revision: "f245870455e8acd9e12d7757e444e919fa79993224ecb71e109fb631272e0d9e"),
        BetaItem(id: "C-AI-03", title: "Tile icons fit the dish", category: "Recipe quality", how: "Ribs show a flame (not a teacup), a chicken sandwich shows a takeaway icon (not a bird), drinks show a cup.", auto: false, revision: "5660c2da27d07d276c2ee6a9f521f24540e6c85fee10eb350178d79aeb97b090"),
