        BetaItem(id: "C-DES-03", title: "Timer summary bar", category: "Design review polish", how: "With 2+ timers running, one compact summary bar shows the soonest timer and '+N more'; tapping it lists all timers with pause/stop.", auto: false, revision: "a20dbd9ef15c8f14be5160b459e1e75be65ad9554e632a947570c16fbf83444e"),
        BetaItem(id: "C-DES-07", title: "Cook mode ✕", category: "Design review polish", how: "Cook mode closes with a top-leading ✕ (labelled 'Close cook mode'); closing with running timers keeps them running and shows them on the timer bar.", auto: false, revision: "ef152f0462de30e71a333481dc758c9b6b5ad9091566d3dc6fd847f8f2836fb7"),
        BetaItem(id: "C-WID-01", title: "Widgets read live data", category: "Widgets, Lock Screen & Control Center", how: "Settings › Beta testing › Widgets says App Group OK and at least one widget kind has loaded; no widget is stuck on 'Open ate'.", auto: true, revision: "ae05df698e0c8fec1c190cd18468897ef498f98a462986b1219df9492021de5e"),
        BetaItem(id: "C-WID-02", title: "Widget gallery polish", category: "Widgets, Lock Screen & Control Center", how: "All five Ate widgets appear in the gallery with names, descriptions and correct previews in light, dark and tinted modes.", auto: false, revision: "4c7f56a5a70bf36aeab0fe217b2634e6f07e427608ff841f6f36b9e6d31dec85"),
        BetaItem(id: "C-WID-03", title: "Lock Screen accessories", category: "Widgets, Lock Screen & Control Center", how: "Circular ring, rectangular step timer and inline shopping item render legibly in every Lock Screen font/colour and update within a few seconds.", auto: false, revision: "ed75ed593649fc9239e4407c72074e9f16e511b62cb831d66b8abffeeba7b52f"),
        BetaItem(id: "C-WID-04", title: "Control Center controls", category: "Widgets, Lock Screen & Control Center", how: "Kitchen timer and Quick add appear in the Controls gallery with icons and labels, and work from the Lock Screen and Action button.", auto: false, revision: "73c88f2f9e68fcc40586960e73f69b9664dc1414b7f9deb2186a2d5cfd587169"),
        BetaItem(id: "C-SIRI-01", title: "Phrases recognised by voice", category: "Siri polish", how: "'Cook Mogodu in Ate', 'What's tonight's pick in Ate' and 'What's on my Ate shopping list' are all handled by Ate by voice, not a web answer; Beta › Siri lists the registered phrases.", auto: true, revision: "64052291f820a47ee8a33f2f7cf86c557f4475dd34001fd9846228e78471632b"),
        BetaItem(id: "C-SIRI-02", title: "Clean Siri dialog", category: "Siri polish", how: "Every Siri reply starts with a capital, has no stray spaces before punctuation, and is never blank.", auto: true, revision: "ce2c34ab4ee2761647294fce854dd9e353289198acfec99da1425ecb65e37d1c"),
