        BetaItem(id: "C-SIRI-04", title: "Fuzzy recipe names", category: "Siri polish", how: "'Cook Mugod' finds Mogodu, ambiguous names ask which one, unknown names say so, and the wrong recipe is never started.", auto: true, revision: "af51c7936e90063f80c8dae1afd6fa891db8228275c2f15e0fab71fa9f71106b"),
        BetaItem(id: "C-FIX-07", title: "Shopping list as Shortcut output", category: "Build 81 fixes", how: "A Shortcut 'What's on my shopping list' with Show When Run off passes the items as text to the next action (e.g. Show Result), not an empty card.", auto: false, revision: "18d195c03b7893f8289db6f6a375012905ae77aef900d9f3ea283f49da878bd4"),
        BetaItem(id: "C-DES-01", title: "Native nav bars", category: "Design review polish", how: "Library, Shopping, Journal and Settings show system large serif titles that collapse on scroll; pushed screens use the system chevron Back and swipe-back; no custom bar chrome.", auto: true, revision: "71e67fc2f929e66bb5315d3f34ad8d3204aace779d19f2e59fd07351fdb6872e"),
        BetaItem(id: "C-DES-02", title: "One bottom area on recipe detail", category: "Design review polish", how: "Cook mode sits directly above a single timer bar; nothing overlaps the tab bar; Ask Ate scrolls clear; the offline strip is at the top.", auto: true, revision: "eca75b219c18d22aaf42589c2d6a472b6e13ce459e9ca729897026fdbd1e50d9"),
