        BetaItem(id: "C-AX-01", title: "AX5 Larger Text", category: "Accessibility", how: "At the largest accessibility text size every screen is readable, nothing is clipped or truncated mid-word, and no fixed-size fonts remain.", auto: true, revision: "71d8a2bd47dd1cb4e51ca67a90ed9c40a4951235b1158e8609e687eb57c02e4f"),
