        BetaItem(id: "C-AX-04", title: "Contrast and Bold Text", category: "Accessibility", how: "With Increase Contrast and Bold Text, muted text and borders darken and fonts get heavier; brand colour pairs are ≥4.5:1.", auto: true, revision: "d286c4d2a2ea4cb9baae778cf38f877304e47e5052ef51a02b5423a1e8d9020f"),
        BetaItem(id: "C-NAT-01", title: "N-01 System chrome only", category: "Native acceptance", how: "Tab bar, nav bars, Back, menus, search and sheet chrome are system; no custom glassEffect without an opaque iOS 18 fallback; cards, buttons, chips and fields stay opaque.", auto: false, revision: "cdff1a8d7dffbfd755287ac0ca064ef87bcf6cb30f526b87683958993e8afe6a"),
