        BetaItem(id: "C-NAT-12", title: "N-12 Increase Contrast + Bold Text", category: "Native acceptance", how: "Muted text and borders darken; custom fonts get heavier with Bold Text.", auto: true, revision: "7260379e6fe26e4979453da1c1fff7bbae9a911bf31190712c96840fcab9319e"),
        BetaItem(id: "C-NAT-13", title: "N-13 Offline / model unavailable", category: "Native acceptance", how: "Typed link/prompt and review drafts are kept offline; Retry works without retyping.", auto: true, revision: "537c2a0435b8262d222b83c4eb9c4ad93cab91050b6fc028ed37ec65ca1498cf"),
        BetaItem(id: "C-COV-01", title: "Fallback cover tile", category: "Covers", how: "A recipe with no image shows the designed plate-and-name tile (never a letter or bird), legible in light and dark mode.", auto: false, revision: "fc4693d8386d40af049c4b74ed3a8ef0c92b546452856f89e022d2a3725f6fc3"),
        BetaItem(id: "C-COV-02", title: "Generate cover", category: "Covers", how: "On an Apple Intelligence iPhone, … › Generate cover makes a new Playground cover in ≤30 s and keeps it after relaunch; elsewhere the option explains why it's unavailable.", auto: true, revision: "8f7460cf071e56f5b6cae9dd36680008777d10915f690798331209f420060411"),
        BetaItem(id: "C-COV-03", title: "Covers everywhere", category: "Covers", how: "The same cover appears in Library, recipe detail, widgets, Spotlight and Siri cards.", auto: false, revision: "1a820d318aaa24dbfc70bc38fe9e6b34d35cc6fd103ba149daf88b9d7d703dac"),
        BetaItem(id: "C-FIX-01", title: "Believable step times", category: "Build 81 fixes", how: "On Nyama yenkomo (and any saved recipe) 'brown beef (2 min)', 'simmer (4 min)', 'pap (3 min)' are gone: implausible AI times show no '(N min)' and no timer, a time written in the step wins, and the card notes that times were corrected.", auto: false, revision: "3e06cc487f7a4ad89d3676339139cfb92ee5832e18c87674e101a50c49b1a3d2"),
        BetaItem(id: "C-FIX-02", title: "No empty steps", category: "Build 81 fixes", how: "At 1x, 2x and 3x servings, in detail and cook mode, there are no empty numbered step bubbles.", auto: false, revision: "8a545f9ce7754053beff74ea44495378824fad1231911218067f1d521a6a6b5d"),
        BetaItem(id: "C-FIX-03", title: "Offline strip below the nav bar", category: "Build 81 fixes", how: "With Wi-Fi and data off, the offline strip sits under the nav bar on Library and recipe detail and never covers the title or back button.", auto: false, revision: "99affa12e4c1a8e685c8b6a53623c311f03c5343f4685fd12bf378bc3fb78d00"),
        BetaItem(id: "C-FIX-04", title: "Real covers in Siri cards", category: "Build 81 fixes", how: "Tonight's pick and Quick recipes from Shortcuts show the recipe photo, or the designed plate tile, never a bare fork-and-knife.", auto: false, revision: "5e4653b2f0d387eb9f680017a5e710c652b0fc292f4ea749eb58f182582be11c"),
        BetaItem(id: "C-FIX-05", title: "Tidy Spotlight", category: "Build 81 fixes", how: "Searching 'Ate' in Spotlight shows at most 3 'Cook …' suggestions (favourites first) with cover thumbnails, not every recipe.", auto: false, revision: "69082feb6a7bad64148ad67a37f315197661c52e7c822a769c528efd6e50bc19"),
        BetaItem(id: "C-FIX-06", title: "Siri voice diagnostics", category: "Build 81 fixes", how: "Beta › Siri explains whether phrases are registered; after opening Ate once, 'What's tonight's pick in Ate' is tried by voice and the result noted (sideloaded installs may need SideStore/Xcode).", auto: false, revision: "142840ac4938b8fc3147606d0299b8b554c1d0adf3de47adfac7c0ef40f11683"),
        BetaItem(id: "C-FIX-08", title: "One save, one recipe", category: "Build 81 fixes", how: "Saving a card, restoring an unsaved card or tapping Save twice never creates copies; the earlier duplicate 'Ribs and lemon pepper wings' copies are merged into one.", auto: false, revision: "18bff49a640ccd8aed52d2364b25f16366c593caf02324d368bc2b65049b1b91"),
        BetaItem(id: "C-LIB-01", title: "Library header", category: "Library header", how: "Library shows the logo in the toolbar, the native large title 'Your Kitchen', 'Search N recipes' in the search bar, a quiet count, and one icon-only Group & sort menu that never truncates.", auto: false, revision: "2c8ad8307d16173ce235bf2a6019ee0ce609040fa60dffbee9e0d258deca4a15"),
        BetaItem(id: "C-TAB-01", title: "Add recipe in the tab bar accessory", category: "iOS 26 tab bar", how: "On iOS 26 a persistent 'Add recipe' control sits above the tab bar on every tab and opens the Add sheet; no floating Add button.", auto: false, revision: "0f1cf3911bc529cfbbb6e8b426677d4c9fee6b944e23af34fc0f3cdcc3fbadaa"),
        BetaItem(id: "C-TAB-02", title: "Timer in the accessory", category: "iOS 26 tab bar", how: "With a timer running, the accessory shows the timer summary plus a + (Add recipe), the old in-app timer bar doesn't also show on tab roots, and recipe detail's Cook mode button never clashes with it.", auto: false, revision: "055a9422962307ff2bfaab7191a4a57b285169de755caa1c7e6c89146eecb274"),
        BetaItem(id: "C-TAB-03", title: "Compact when minimised", category: "iOS 26 tab bar", how: "Scrolling down minimises the tab bar and the accessory switches to its compact layout; scrolling up restores both.", auto: false, revision: "7bb5bb9014a584dca32d4effde42f488c6eb8ea64a00827c6056e722253b9818"),
        BetaItem(id: "C-TAB-04", title: "Search tab", category: "iOS 26 tab bar", how: "Library search sits in the tab bar (search tab) next to the 4 main tabs, and 'Your Kitchen' stays visible while searching.", auto: false, revision: "6e05bdc2b24587686da98e01f3aeef4fd25760a6cb1ff546d81d9bd2a0cace92"),
        BetaItem(id: "C-TAB-05", title: "Soft scroll edges", category: "iOS 26 tab bar", how: "Library, Shopping, Journal and Settings fade softly under the nav bar when scrolled.", auto: false, revision: "3c4ff14af983f66e3d06b6cecd2e82ae0b9ebb95bb8a2070677f0cce1f1d1ad5"),
        BetaItem(id: "C-TAB-06", title: "Concentric sheet cards", category: "iOS 26 tab bar", how: "Cards inside the Add/Review sheet follow the sheet's corner curve.", auto: false, revision: "e8c0989cd9ab49c23c78dc8b24b668543d9bbcec04571eeb32cd6301eeaa293f"),
        BetaItem(id: "C-NUT-01", title: "Configure local nutrition goals", category: "Nutrition tracking", how: "Given Settings › Nutrition goals, When I enable any target, enter a valid value, save, reopen and optionally clear all, Then each target persists independently in local storage, invalid values are explained inline, and clearing followed by Save removes every configured target.", auto: false, revision: "d319fdde14e4e58348a4cf4411093fe19af985aca3205ea8da743ede7d7d32ed"),
        BetaItem(id: "C-NUT-02", title: "Explicit local food diary and daily totals", category: "Nutrition tracking", how: "Given Settings › Food diary, When I log a food or recipe snapshot, Then its selected local calendar day, meal, quantity, servings, source/provenance and optional per-serving nutrient snapshot are stored locally; the calendar day remains stable if the device time zone changes; cooking completion does not create an entry; daily values scale by servings and compare with configured goals; any nutrient missing from an entry is shown as unavailable, never estimated; I can delete an entry.", auto: false, revision: "c2fd70caebb56881fa722862cec027850e550111c4901b4fe22a95403278dc2b"),
        BetaItem(id: "C-NUT-03", title: "Show complete source-backed recipe nutrition estimates", category: "Nutrition tracking", how: "Given a recipe with supported ingredients and quantities, When I open Recipe detail, Then verified source-backed records with reviewed usage rights and supported quantities contribute to the estimate; incomplete recipes never show partial totals as complete; energy, protein, carbohydrate, fat and fibre use canonical units and explicit rounding.", auto: false, revision: "e3a5c400e313d748a8fb48b04931ebc0307f9675295f4c328251708e9fbe59b3"),
        BetaItem(id: "C-NUT-04", title: "Preserve nutrition goals when local storage fails", category: "Nutrition tracking", how: "Given Settings › Nutrition goals, When a save or clear operation fails, Then the app reports the error and keeps the prior configuration available; successful saves use atomic file writes, and legacy UserDefaults values migrate only after a successful write; read or decode failures are never presented as an empty configuration.", auto: false, revision: "f507b50344f055bf64ef8aa7fdd7e97bbd8cbbb63909ab2590956c5f54efdf23"),
        BetaItem(id: "C-JRN-01", title: "Journal entry opens on its own", category: "Journal", how: "Tapping an entry in the Journal tab opens a detail view with the full text, date, state, and any linked recipe, location or media.", auto: true, revision: "87612a88b9ced1da6a54cfe7889b4f35291f604f9c18457d8ff0f33e57a5cf51"),
        BetaItem(id: "C-JRN-02", title: "Journal list with search", category: "Journal", how: "The Journal tab lists every entry newest first; searching by words, place or state filters it, and an empty search says so.", auto: false, revision: "d795128b9977135ac294df2d0fb58785939795b35b7a7e7f06f6e9b9c4ec294c"),
        BetaItem(id: "C-JRN-03", title: "Edit an entry", category: "Journal", how: "… › Edit opens the text in a sheet; Save updates it and shows 'Edited'; Cancel or swipe-down never loses the original.", auto: true, revision: "2c660da7496f1a6bceac16bbc1e4bf570ddbc47e9440b82362e2f9a6d53cacbd"),
        BetaItem(id: "C-JRN-04", title: "Delete with confirmation", category: "Journal", how: "… › Delete asks in a confirmation dialog with a safe Cancel; Delete removes the entry and its media and goes back to the list.", auto: true, revision: "02199c47642dba6288c0b34b52112911ddf27d76e30ab1478b15c0f269c37d97"),
        BetaItem(id: "C-JRN-05", title: "Share an entry", category: "Journal", how: "Share sends the date, state, text and place as plain text via the share sheet.", auto: false, revision: "5bc7a5ae693c671ca34a0e27e86c7a55abb74e782e9e52eb1edfd0198f6da912"),
        BetaItem(id: "C-JRN-06", title: "Shortcuts Open journal entry", category: "Journal", how: "The 'Open journal entry' action in Shortcuts lets me pick an entry and opens its detail view in Ate; a deleted entry gives a clear error.", auto: true, revision: "6a52d1485d070270c65762fe49a21d217ee04a7c2a48c7955dece35bd583cc72"),
        BetaItem(id: "C-JRN-07", title: "Location and media from Siri/Shortcuts", category: "Journal", how: "'New journal entry' with a Location and Media Items saves them; the entry detail shows the place (with a map) and the photos.", auto: false, revision: "d943a250cbae65e59acbfd73b25e3bfb9ce7128b3b117cae9f52dd28b23a516e"),
        BetaItem(id: "C-JRN-08", title: "Image prompts are never journal entries", category: "Journal", how: "Sending an image-generation prompt (e.g. 'A top-down, highly detailed photograph…') to New journal entry is refused with a clear message, and old ones are cleaned up.", auto: true, revision: "a3c8452e1714adab5f47bc19489b3f8dc7265828bb9fb646a939cee790d445a6"),
        BetaItem(id: "C-POL-06", title: "Staging Supabase project for end-to-end tests", category: "Polish", how: "CI runs auth/share/sync E2E against staging when secrets exist.", auto: false, revision: "60551391c047676ca7117afb0e5d41ff2b361546a785912c6dbcf1ed724536a7"),
        BetaItem(id: "C-POL-03", title: "Watch app", category: "Polish", how: "Running timers mirror to Apple Watch.", auto: false, revision: "dea5f7cfb01fa3849049ec7f6266dcc9f53f1c36fed8dfaeab42f2f7e48f3537"),
        BetaItem(id: "C-POL-04", title: "iPad and foldable layouts", category: "Polish", how: "Sidebar/grid used on iPad with no layout breaks.", auto: false, revision: "0ec1fc4d3f6013dcba444bed5ce613b8017cdc2bbdc4bf6a5ac2e9d55716aba8"),
        BetaItem(id: "C-POL-05", title: "Modularise auth/sync/AI/share/timers/deep links", category: "Polish", how: "Each area is its own module with its own tests.", auto: false, revision: "aab8d2c13c7598531d3373914ca5cc0819dd60a5aa65e1104932c858678822d7"),
    ]
    /// The checklist for this build channel: pilot builds show Pilot-gate items; TierC compatibility builds show uncommitted-gate items.
    static var isTierC: Bool { AppConfig.channel.uppercased() == "TIERC" }
    static var tierName: String { isTierC ? "Uncommitted work" : "Pilot gate" }
    static var items: [BetaItem] { isTierC ? tierC : tierA }
    static var all: [BetaItem] { tierA + tierC }
    static var categories: [String] { var seen: [String] = []; for i in items where !seen.contains(i.category) { seen.append(i.category) }; return seen }
}
